head.script:
scwin.screenId = "jldfil25001";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "if_availableModify", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "availableModify" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("availableModify"))); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// [A] 초기 목록 미해결 — jldfil25001: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_conds();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil25001.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.grd_corpMiscInfoChgList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_corpMiscInfoChgList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_corpMiscInfoChgList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_corpMiscInfoChgList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (r["applDateYn"] === 'Y' || r["applDateYn"] !== 'V') { if (typeof scwin.goURL === 'function') { await scwin.goURL("modi", r["bzProcsNo"], r["applDateYn"]); } else { console.error('[sdd] 행 동작 미정의: scwin.goURL (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.goURL'); } return; }
        if (typeof scwin.alert === 'function') { scwin.alert("수정 가능한 상태가 아닙니다."); } else { console.error('[sdd] 행 동작 미정의: scwin.alert (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.alert'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_corpMiscInfoChgList.oncellclick' });
    }
};

/**
 * @event
 * @name scwin.btn_GoURL_2_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_GoURL_2_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_GoURL_2_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.goURL('req','','Y')
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil25001.btn_GoURL_2_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_GoURL
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_GoURL = async function () {
    try { return await $c.data.downFile("/account/corporationReport.do", "", ($c.util.getComponent("dma_GoURLReq") ? $c.util.getComponent("dma_GoURLReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.goURL
 * @author Inswave
 * @date 2026. 09. 29
 * @param _target _bzProcsNo applDateYn
 * @returns
 * @hidden N
*/
scwin.goURL = async function (_target, _bzProcsNo, applDateYn) {
    /* sdd-asis-lifecycle:begin fn_GoURL — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    (document.corpForm || { elements: [] }).action = "corporationReport.do";
    $c.util.getComponent('dma_GoURLReq').set('method', "searchCorporationReport");
    $c.util.getComponent('dma_GoURLReq').set('viewFlag', _target);
    $c.util.getComponent('dma_GoURLReq').set('applDateYn', applDateYn);
    $c.util.getComponent('dma_GoURLReq').set('bzProcsNo', _bzProcsNo);
    await scwin.tx_fn_GoURL();
    /* sdd-asis-lifecycle:end */
};
